contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log1, address _log2) public payable {
        bool reverted1;
        c.SetLogFile(_log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted2;
        c.SetLogFile(_log2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        assert(!reverted1 && reverted2);
    }

    receive() external payable {}
}

