        try c.Initialized() {} catch { return; }
        bool reverted2;
        try c.SetLogFile(_log2) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 && reverted2);
    }

    function testFuzz_run(address _log1, address _log2) public {
